package com.tyami.forlaism.item;
import com.tyami.forlaism.ForalisItem; import com.tyami.forlaism.registry.Fluids; import com.tyami.forlaism.world.TimeAccelerationManager; import net.minecraft.ChatFormatting; import net.minecraft.core.BlockPos; import net.minecraft.nbt.CompoundTag; import net.minecraft.network.chat.Component; import net.minecraft.world.InteractionResult; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.TooltipFlag; import net.minecraft.world.item.context.UseOnContext; import net.minecraft.world.level.Level; import net.minecraftforge.common.capabilities.ForgeCapabilities; import net.minecraftforge.common.capabilities.ICapabilityProvider; import net.minecraftforge.fluids.FluidStack; import net.minecraftforge.fluids.capability.IFluidHandler; import net.minecraftforge.fluids.capability.IFluidHandlerItem; import net.minecraftforge.fluids.capability.templates.FluidHandlerItemStack; import org.jetbrains.annotations.NotNull; import org.jetbrains.annotations.Nullable; import java.util.List;
public class TokinoStaffTier2Item extends ForalisItem {public static final int CAPACITY=10000,CONSUMPTION_PER_USE=100;public TokinoStaffTier2Item(Properties p){super(p.stacksTo(1));}@Override public ICapabilityProvider initCapabilities(ItemStack s,@Nullable CompoundTag n){return new FluidHandlerItemStack(s,CAPACITY){@Override public boolean isFluidValid(int t,@NotNull FluidStack f){return f.getFluid()==Fluids.FO.get();}};}@Override public InteractionResult useOn(UseOnContext c){Level l=c.getLevel();BlockPos p=c.getClickedPos();IFluidHandlerItem h=c.getItemInHand().getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElse(null);if(h!=null&&!TimeAccelerationManager.isAccelerated(l,p)&&h.drain(new FluidStack(Fluids.FO.get(),CONSUMPTION_PER_USE),IFluidHandler.FluidAction.SIMULATE).getAmount()>=CONSUMPTION_PER_USE){if(!l.isClientSide){h.drain(new FluidStack(Fluids.FO.get(),CONSUMPTION_PER_USE),IFluidHandler.FluidAction.EXECUTE);TimeAccelerationManager.accelerate(l,p,320,64);}return InteractionResult.sidedSuccess(l.isClientSide);}return InteractionResult.PASS;}@Override public boolean isBarVisible(ItemStack s){return true;}@Override public int getBarWidth(ItemStack s){IFluidHandlerItem h=s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElse(null);return h==null?0:Math.round(13f*h.getFluidInTank(0).getAmount()/CAPACITY);}@Override public void appendHoverText(ItemStack s,@Nullable Level l,List<Component> t,TooltipFlag f){IFluidHandlerItem h=s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElse(null);int a=h==null?0:h.getFluidInTank(0).getAmount();t.add(Component.literal("FO: "+a+" / "+CAPACITY+" mB").withStyle(ChatFormatting.AQUA));t.add(Component.translatable("tooltip.forlaism.tokino_staff_tier2_desc").withStyle(ChatFormatting.GRAY));}}
